    def __init__(self):
        self.valves = self.Valves()
        self._data = None

    def _load(self):
        if self._data: return self._data
        self._data = json.loads(self.valves.price_data)
        return self._data

    def _tokenize(self, text: str):
        """Split text into meaningful tokens for fuzzy matching."""
        # Split on spaces and common delimiters
        import re
        tokens = re.split(r"[\s,/.()\-]+", text.lower())
        # Keep tokens >= 2 chars, filter noise
        noise = {"for","and","the","with","pdf","file","2026","y2026","การ","จะ","ให้","ด้วย","เพื่อ","อย่าง","เป็น","ที่","มี"}
        return [t for t in tokens if len(t) >= 2 and t not in noise]

    def _match_score(self, query: str, item_name: str):
        """Calculate fuzzy match score 0.0-1.0 between query and item name."""
        q_tokens = self._tokenize(query)
        n_tokens = self._tokenize(item_name)
        if not q_tokens:
            return 0.0
        # Count matching tokens
        matched = 0
        for qt in q_tokens:
            for nt in n_tokens:
                if qt in nt or nt in qt:
                    matched += 1
                    break
        # Also check if full query is a substring
        if query.lower() in item_name.lower():
            matched = max(matched, len(q_tokens))
        return matched / len(q_tokens)

    def _find_best(self, query: str, sheet_filter: Optional[str] = None):
        """Find best matching item across all sheets. Returns (sheet, item, score)."""
        data = self._load()
        best_score = 0.0
        best_result = None
        all_matches = []
        for sn, items in data.items():
            if sheet_filter and sheet_filter not in sn:
                continue
            for item in items:
                nm = item.get("n", "")
                score = self._match_score(query, nm)
                if score > 0:
                    all_matches.append((sn, item, score))
                if score > best_score:
                    best_score = score
                    best_result = (sn, item, score)
        # Sort all_matches by score desc
        all_matches.sort(key=lambda x: x[2], reverse=True)
        return best_result, all_matches[:10]

    async def search_items(self, query: str, limit: int = 10) -> str:
        """
        Fuzzy search for items by keyword(s).
        Use short Thai or English keywords like "ร่มโค้ก", "A4", "เสื้อโปโล".
        Returns top matching items with scores, categories, and prices.
        For composite jobs (e.g. print+bind+laminate), call multiple times with different keywords.
        """
        _, matches = self._find_best(query)
        if not matches:
            return json.dumps({"found": False, "query": query, "hint": "ลองใช้ keyword สั้นๆ เช่น ร่มโค้ก, A4, เสื้อยืด"}, ensure_ascii=False)
        results = []
        for sn, item, score in matches[:limit]:
            results.append({
                "sheet": sn,
                "item": item["n"],
                "score": round(score, 2),
                "unit_price": item.get("p", 0),
                "vendor": item.get("v", ""),
                "tiers": item.get("t", [])[:5],
            })
        return json.dumps({"found": True, "count": len(results), "results": results}, ensure_ascii=False)

    async def lookup_price(self, item_name: str, quantity: int, color_type: Optional[str] = None) -> str:
        """
        Search price from embedded JSON.
        Use SHORT keywords like "ร่มโค้ก 36 นิ้ว", "Sale kit A4", "A4 230g".
        Do NOT pass long descriptions. Break compound requests into separate calls.
        """
        # Fuzzy match
        best, _ = self._find_best(item_name)
        if not best:
            return json.dumps({"found": False, "query": item_name, "hint": "ไม่พบรายการ ลองใช้ keyword สั้นๆ หรือใช้ search_items ค้นหาก่อน"}, ensure_ascii=False)
        sn, item, score = best
        nm = item["n"]
        p = item.get("p", 0)
        v = item.get("v", "")
        tiers = item.get("t", [])

        # Determine pricing based on sheet type
        if "POSM" in sn:
            return json.dumps({"found": True, "match_score": round(score,2), "item": nm, "unit": p, "total": p * quantity, "vendor": v, "source": "Excel>JSON"}, ensure_ascii=False)

        elif "Printing(MKT)" in sn or "Printing-Rate" in sn:
            if tiers:
                sorted_tiers = sorted(tiers, key=lambda x: x["q"])
                best_tier = sorted_tiers[0]
                for t in sorted_tiers:
                    if t["q"] <= quantity:
                        best_tier = t
                return json.dumps({"found": True, "match_score": round(score,2), "item": nm, "unit": best_tier["p"], "total": best_tier["p"] * quantity, "vendor": v, "tier_used": best_tier["q"], "source": "Excel>JSON"}, ensure_ascii=False)
            else:
                return json.dumps({"found": True, "match_score": round(score,2), "item": nm, "unit": p, "total": p * quantity, "vendor": v, "source": "Excel>JSON"}, ensure_ascii=False)

        elif "Garment" in sn:
            adj = {"อ่อน": 5, "กลาง": 10, "เข้ม": 20}.get(color_type, 0)
            for t in tiers:
                lo = t.get("lo", 0)
                hi = t.get("hi", 999999)
                if lo <= quantity <= hi:
                    up = t["p"] + adj
                    return json.dumps({"found": True, "match_score": round(score,2), "item": nm, "unit": up, "total": up * quantity, "vendor": v, "color_adj": f"+{adj}" if adj else "", "source": "Excel>JSON"}, ensure_ascii=False)
            if tiers:
                t = tiers[-1]
                up = t["p"] + adj
                return json.dumps({"found": True, "match_score": round(score,2), "item": nm, "unit": up, "total": up * quantity, "source": "Excel>JSON"}, ensure_ascii=False)
            return json.dumps({"found": True, "match_score": round(score,2), "item": nm, "unit": p, "total": p * quantity, "vendor": v, "source": "Excel>JSON (no tier match)"}, ensure_ascii=False)

        elif "Premium" in sn:
            if tiers:
                best_tier = tiers[0]
                for t in tiers:
                    try:
                        tq = int(str(t["q"]).replace(",", ""))
                    except:
                        tq = 0
                    if tq <= quantity:
                        best_tier = t
                return json.dumps({"found": True, "match_score": round(score,2), "item": nm, "unit": best_tier["p"], "total": best_tier["p"] * quantity, "vendor": v, "tier_used": best_tier["q"], "source": "Excel>JSON"}, ensure_ascii=False)
            return json.dumps({"found": True, "match_score": round(score,2), "item": nm, "unit": p, "total": p * quantity, "vendor": v, "source": "Excel>JSON"}, ensure_ascii=False)

        return json.dumps({"found": False, "hint": f"Unknown sheet type: {sn}"}, ensure_ascii=False)

    async def health_check(self) -> str:
        try:
            data = self._load()
            total = sum(len(v) for v in data.values())
            sheets = list(data.keys())
            return json.dumps({"status": "ok", "items": total, "sheets": sheets, "source": "Excel>JSON embedded"}, ensure_ascii=False)
        except Exception as e:
            return json.dumps({"status": "error", "detail": str(e)})
